INSERT INTO Language_ko_KR (Tag, Text)
VALUES	('TXT_KEY_BUILDING_MOVIE_THEATRE',			'영화관'),
		('TXT_KEY_BUILDING_MOVIE_THEATRE_TEXT',		'영화관은 대중의 오락을 위해 영화를 상영하는 강당을 갖춘 사업체입니다. 대부분은 표를 구매하여 참여하는 일반 대중을 대상으로 하는 상업적 행사입니다. 20세기 초에 처음으로 대중 영화가 상영된 곳은 기존의 (보드빌) 극장이나 관객이 편안하게 앉을 수 있고 어두울 수 있는 장소에서 이루어졌으며, 마법의 등불 쇼나 엿보기 쇼와 같은 이전의 오락 형태를 계승했습니다.[NEWLINE][NEWLINE]영화 제작과 상영은 그 공정이 발명되자마자 수익의 원천이 되었습니다. 1917년에 찰리 채플린은 연봉 100만 달러를 받는 계약을 맺었습니다. 그 이후로 영화 산업은 전 세계적으로 가장 영향력 있는 산업 중 하나가 되었으며, 2018년에는 시장 가치가 1,360억 달러에 달했습니다. 뉴스 영화(그리고 나중에는 텔레비전)는 오락과 더불어 정보, 교육, 선전에 대한 접근성을 혁신적으로 변화시켰습니다.[NEWLINE][NEWLINE]2010년대 이후, 대부분의 영화관은 디지털 영화 상영 장비를 갖추게 되면서 더 이상 무거운 릴에 실제 필름을 인화하여 운반할 필요가 없게 되었습니다. 촬영부터 배포까지 전체 과정을 디지털화하여 영화 제작과 감상에 대한 접근성을 대폭 확대할 수 있습니다.'),
		('TXT_KEY_BUILDING_MOVIE_THEATRE_STRATEGY',	'영화관은 문화 계열에서 갈라져 나와 문화 전문가의 생산량을 늘려주므로 길드 도시에서는 꼭 필요한 시설입니다. 사막 지형과 소도시와 마을에 혜택을 제공하며 행복도를 높여 다른 도시에서도 강력한 선택이 될 수 있습니다. 마지막으로, 다른 일부 건물과 마찬가지로 컴퓨터 기술을 연구하면 추가 생산량을 얻을 수 있으므로, 이미 영화관 건설에 전념했다면 수익성 있는 목표가 될 수 있습니다.'),
		('TXT_KEY_BUILDING_MOVIE_THEATRE_HELP',		'이 도시의 [ICON_VP_WRITER] 작가, [ICON_VP_ARTIST] 예술가, [ICON_VP_MUSICIAN] 음악가 전문가로부터 [ICON_GOLD] 골드, [ICON_RESEARCH] 과학, [ICON_CULTURE] 문화가 +2만큼 증가합니다. 이 도시에서 작업하는 사막 타일에서 [ICON_GOLD] 골드와 [ICON_TOURISM] 관광이 +1 증가합니다. [COLOR_CYAN]컴퓨터[ENDCOLOR]를 발견하면 [ICON_RESEARCH] 과학 +4, [ICON_CULTURE] 문화 +2가 증가합니다.[NEWLINE][NEWLINE]마을과 소도시: [ICON_RESEARCH] 과학 +2');